using System.ComponentModel.DataAnnotations; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using PetShop.Web.Data;
namespace PetShop.Web.Pages.Products;
public sealed class IndexModel(ApplicationDbContext db,UserManager<IdentityUser> users,TimeProvider clock):PageModel
{
 public List<Product> Products{get;private set;}=[];[BindProperty]public InputModel Input{get;set;}=new();
 public async Task OnGetAsync()=>await LoadAsync();
 public async Task<IActionResult> OnPostCreateAsync(){if(!ModelState.IsValid){await LoadAsync();return Page();}var user=await users.GetUserAsync(User);var now=clock.GetLocalNow();var p=new Product{Name=Input.Name.Trim(),Sku=Input.Sku?.Trim()??string.Empty,Barcode=Input.Barcode?.Trim()??string.Empty,SalePrice=Input.Price,StockQuantity=Input.Stock,LowStockThreshold=Input.LowStock,CreatedAt=now};db.Products.Add(p);if(Input.Stock!=0)db.InventoryTransactions.Add(new InventoryTransaction{Product=p,Kind=InventoryKind.Opening,QuantityChange=Input.Stock,QuantityAfter=Input.Stock,SourceDocumentId=p.Id,OperatorUserId=user!.Id,Note="建档期初库存",CreatedAt=now});await db.SaveChangesAsync();TempData["Success"]="商品已建立。";return RedirectToPage();}
 public async Task<IActionResult> OnPostAdjustAsync(Guid id,decimal change,string note){var p=await db.Products.SingleOrDefaultAsync(x=>x.Id==id);if(p is null)return NotFound();if(change==0||p.StockQuantity+change<0){TempData["Error"]="调整数量不能为零，且结果库存不能为负。";return RedirectToPage();}var user=await users.GetUserAsync(User);var now=clock.GetLocalNow();p.StockQuantity+=change;db.InventoryTransactions.Add(new InventoryTransaction{ProductId=p.Id,Kind=change>0?InventoryKind.Purchase:InventoryKind.Adjustment,QuantityChange=change,QuantityAfter=p.StockQuantity,SourceDocumentId=Guid.NewGuid(),OperatorUserId=user!.Id,Note=string.IsNullOrWhiteSpace(note)?"手工库存调整":note.Trim(),CreatedAt=now});await db.SaveChangesAsync();TempData["Success"]="库存已调整。";return RedirectToPage();}
 private async Task LoadAsync()=>Products=await db.Products.AsNoTracking().OrderBy(x=>x.StockQuantity<=x.LowStockThreshold).ThenBy(x=>x.Name).ToListAsync();
 public sealed class InputModel{[Required,StringLength(80)]public string Name{get;set;}="";[StringLength(50)]public string Sku{get;set;}="";[StringLength(80)]public string Barcode{get;set;}="";[Range(0.01,999999)]public decimal Price{get;set;}[Range(0,999999)]public decimal Stock{get;set;}[Range(0,999999)]public decimal LowStock{get;set;}=3;}
}
